insert into public.tours (slug, title, subtitle, category, subtype, region, cover_image, gallery, price, distance, duration, difficulty, elevation_gain, stay, languages, capacity, spots_left, badge, season, season_from, season_to, departure_point, departure_time, return_info, transport, group_size, walking_per_day, summary, lat, lng, itinerary, included, excluded, published)
values
  ('svaneti-mestia-ushguli', 'Mestia – Ushguli Trek', 'Mestia → Ushguli trek', 'hiking', null, 'Svaneti', '/assets/svaneti(1).webp', array['/assets/svaneti.jpg','/assets/Svaneti.jpe','/assets/Svaneti-history.jpg','/assets/svaneti(1).webp','/assets/camping.jpg'], 890, '58 km', '4 days / 3 nights', 'Hard', '2,400 m', 'Guesthouse', 'EN · GE · RU', 12, 5, 'top', 'June – October', '06-15', '10-15', 'Tbilisi, Liberty Square', '07:00', 'Day 4, ~21:00 Tbilisi', 'Minibus + 4x4 to trailhead', '6 – 12 people', '5 – 7 hours', 'A four-day traverse through Upper Svaneti, from Mestia to Ushguli — one of the highest permanently inhabited villages in Europe. You walk ridge to ridge with Shkhara and Tetnuldi in view most of the day, sleeping in family guesthouses along the way.', 43.0451, 42.728, '[["Tbilisi → Mestia","Leave Liberty Square at 07:00. Road transfer through Zugdidi with lunch on the way, arriving in Mestia late afternoon. Short walk to the Mikhail Khergiani museum and an early night."],["Mestia → Zhabeshi","First walking day along the Mulakhi valley. Gentle climbs, Svan towers in every village, and a first proper look at Tetnuldi."],["Zhabeshi → Adishi → Iprari","The big day: the Chkhutnieri pass, a river crossing by horse, and the Adishi glacier viewpoint."],["Iprari → Ushguli → Tbilisi","Morning walk into Ushguli, time at the Lamaria church under Shkhara, then the long drive back to Tbilisi."]]'::jsonb, '[]'::jsonb, '[]'::jsonb, true),
  ('kazbegi-gergeti', 'Kazbegi – Gergeti Trinity & Glacier', 'Gergeti Trinity & glacier', 'hiking', null, 'Mtskheta-Mtianeti', '/assets/sameba.webp', array['/assets/sameba.jpe','/assets/sameba.webp','/assets/Svaneti-history.jpg','/assets/camping.jpg'], 320, '14 km', '2 days / 1 night', 'Medium', '1,300 m', 'Guesthouse', 'EN · GE · RU', 16, 9, 'top', 'June – October', '06-01', '10-31', 'Tbilisi, Liberty Square', '08:00', 'Day 2, ~20:00 Tbilisi', 'Minibus + 4x4 to Gergeti', '8 – 16 people', '4 – 6 hours', 'The classic Georgian view: Gergeti Trinity church on its ridge with Mount Kazbek behind it. Day one walks up to the church and on toward the Gergeti glacier; day two is an easier valley loop before the drive home along the Georgian Military Road.', 42.6572, 44.6417, '[["Tbilisi → Stepantsminda → Gergeti","Drive the Georgian Military Road with stops at Ananuri fortress and the Jvari pass. Afternoon climb to Gergeti Trinity for sunset, then down to the guesthouse."],["Glacier viewpoint → Tbilisi","Early start toward the Gergeti glacier moraine for the Kazbek face, back down for a late lunch, and the drive to Tbilisi."]]'::jsonb, '[]'::jsonb, '[]'::jsonb, true),
  ('tavkvetili', 'Tavkvetili Mountain Day Hike', 'თავკვეთილი', 'hiking', null, 'Tsalka', '/assets/hiking.svg', array['/assets/hiking.svg','/assets/camping fier.webp','/assets/Svaneti-history.jpg'], 90, '12 km', 'Single day', 'Medium', '650 m', 'Day trip', 'EN · GE', 20, 14, 'new', 'May – November', '05-15', '11-15', 'Tbilisi, Liberty Square', '07:30', 'Same day, ~19:30 Tbilisi', 'Minibus to the trailhead', '8 – 20 people', '5 – 6 hours', 'A flat-topped volcanic cone on the Tsalka plateau, close enough to Tbilisi for a single day out. Open grassland the whole way up, wildflowers through early summer, and a summit panorama over the Trialeti range and the reservoir.', 41.5947, 44.0958, '[["Tbilisi → Tsalka → summit → Tbilisi","Two-hour drive to the plateau, a steady walk up open slopes to the crater rim, lunch at the top with the Trialeti range laid out below, then back down the same way and home by evening."]]'::jsonb, '[]'::jsonb, '[]'::jsonb, true),
  ('rkoni', 'Rkoni Canyon & Monastery Camp', 'Canyon & monastery camp', 'camping', null, 'Shida Kartli', '/assets/camping.jpg', array['/assets/camping.jpg','/assets/camping fier.webp','/assets/hiking.svg'], 190, '9 km', '2 days / 1 night', 'Easy', '350 m', 'Tents', 'EN · GE', 18, 11, 'new', 'May – October', '05-01', '10-31', 'Tbilisi, Liberty Square', '09:00', 'Day 2, ~18:00 Tbilisi', 'Minibus + short 4x4 section', '6 – 18 people', '2 – 4 hours', 'An easy weekend in the Tedzami gorge. A gentle riverside walk leads to the 7th-century Rkoni monastery and the old arched bridge, and camp is pitched in the meadow beside the water — the kind of trip that works for families and first-time campers.', 41.926, 44.24, '[["Tbilisi → Rkoni → camp","Drive out past Kaspi, walk the gorge path to the monastery and the medieval bridge, then pitch camp in the meadow and cook dinner over the fire."],["Canyon walk → Tbilisi","Morning wander further up the canyon to the swimming pools, pack up after lunch and drive back."]]'::jsonb, '[]'::jsonb, '[]'::jsonb, true),
  ('black-rock-lake', 'Black Rock Lake Camp', 'Abudelauri valley camp', 'camping', null, 'Racha', '/assets/camping fier.webp', array['/assets/camping fier.webp','/assets/camping.jpg','/assets/Svaneti-history.jpg'], 450, '22 km', '3 days / 2 nights', 'Medium', '1,100 m', 'Tents', 'EN · GE · RU', 14, 0, null, 'June – October', '06-15', '10-15', 'Tbilisi, Liberty Square', '07:00', 'Day 3, ~21:00 Tbilisi', 'Minibus + 4x4 to the trailhead', '6 – 14 people', '4 – 6 hours', 'Two nights under canvas beside one of the high lakes below the Greater Caucasus ridge. The walk in climbs through pine forest and alpine meadow, and the reward is a still black lake that mirrors the peaks at dawn.', 42.546, 45.12, '[["Tbilisi → trailhead → forest camp","Long drive north, then a first afternoon walk through pine forest to the lower camp beside the river."],["Camp → Black Rock Lake → camp","The main day: up through the meadows to the lake, a long stop on the shore, and back down to camp for dinner."],["Camp → Tbilisi","Pack up after breakfast, walk out to the road and drive back to Tbilisi."]]'::jsonb, '[]'::jsonb, '[]'::jsonb, true),
  ('gudauri-freeride', 'Gudauri Freeride Week', 'Freeride week', 'ski', 'freeride', 'Gudauri', '/assets/gudauri.webp', array['/assets/gudauri.jpe','/assets/gudauri.webp','/assets/gudauri%201.jpe','/assets/skier-gudauri-yellow-jacket-768x512.jpg'], 1750, '—', '6 days / 5 nights', 'Hard', '—', 'Hotel', 'EN · GE · RU', 10, 3, 'top', 'December – April', '12-01', '04-15', 'Tbilisi, Liberty Square', '09:00', 'Day 6, ~18:00 Tbilisi', 'Minibus transfer both ways', '4 – 10 people', 'Riding days, 5 – 6 hours', 'Six days riding the wide open bowls above Gudauri with a freeride guide. Lift-accessed off-piste every day, an avalanche-safety session on day one, and a cat or heli option when conditions line up. For confident off-piste riders only.', 42.4769, 44.4783, '[["Transfer & avalanche briefing","Drive up the Georgian Military Road, collect hire gear, and run the transceiver and companion-rescue session on the slope behind the hotel."],["Warm-up riding","Lift laps to read the group and pick lines for the week."],["Bowls above Kobi","The long open descents on the north side, with a guide-set skin track for the last pitch."],["Ridge lines","Steeper terrain if the snowpack allows, mellow trees if it does not."],["Cat or heli day","Weather-dependent optional add-on, otherwise a full lift day."],["Last laps → Tbilisi","Morning riding, lunch in resort, then the transfer back to the city."]]'::jsonb, '[]'::jsonb, '[]'::jsonb, true),
  ('tbilisi-transfer', 'Private Transfer', 'Anywhere in Georgia', 'transfer', null, 'Country-wide', '/assets/transfer.svg', array['/assets/transfer.svg'], 90, null, '1 day', '—', null, null, 'EN · GE · RU', 4, 4, 'new', 'All year', '01-01', '12-31', 'Anywhere you say', null, null, 'Sedan or minibus, by group size', '1 – 4 people', null, 'Airport pickups, and transfers to the trailhead, the resort or the next region. Tell us where and when, how many of you there are and how much luggage — we arrange the vehicle and the driver.', 41.7151, 44.8271, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, true),
  ('gudauri-lessons', 'Gudauri Ski & Snowboard Lessons', 'Ski & snowboard lessons', 'ski', 'lessons', 'Gudauri', '/assets/skier-gudauri-yellow-jacket-768x512.jpg', array['/assets/skier-gudauri-yellow-jacket-768x512.jpg','/assets/gudauri.webp','/assets/ski.svg'], 120, null, '2 hours per lesson', null, null, null, 'EN · GE · RU', 6, 6, null, 'December – April', '12-01', '04-15', 'Gudauri, bottom of Gondola 1', null, null, null, '1 – 6 people', null, 'Private and small-group lessons with a certified instructor, on the slope you are already on. Tell us the day, the time, how many of you there are, what you can already do and what you want to work on — first turns, park laps or riding off-piste safely.', 42.4769, 44.4783, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, true),
  ('bakuriani-beginners', 'Bakuriani Beginner Ski Camp', 'Beginner ski camp', 'ski', 'lessons', 'Samtskhe-Javakheti', '/assets/skier-gudauri-yellow-jacket-768x512.jpg', array['/assets/skier-gudauri-yellow-jacket-768x512.jpg','/assets/gudauri.webp','/assets/ski.svg'], 980, '—', '4 days / 3 nights', 'Easy', '—', 'Hotel', 'EN · GE · RU', 15, 8, null, 'December – March', '12-15', '03-31', 'Tbilisi, Liberty Square', '08:30', 'Day 4, ~19:00 Tbilisi', 'Minibus transfer both ways', '6 – 15 people', 'Two 2-hour lessons daily', 'Four days on the gentlest slopes in Georgia, built for people who have never clipped into a binding. Small groups, two lessons a day, and enough free time to actually practise what you learned in the morning.', 41.7497, 43.5322, '[["Transfer & first lesson","Drive to Bakuriani, fit hire gear, and a first afternoon on the nursery slope — sliding, stopping, getting up."],["Turning","Two lessons on the green runs, working from a snowplough toward linked turns."],["First chairlift","Riding the lift and taking a full blue run top to bottom."],["Free morning → Tbilisi","Last practice run with the instructor, lunch, then the transfer home."]]'::jsonb, '[]'::jsonb, '[]'::jsonb, true),
  ('mtskheta', 'Mtskheta — Ancient Capital Day Tour', 'Ancient capital day tour', 'culture', null, 'Mtskheta', '/assets/mtskheta.svg', array['/assets/mtskheta.svg','/assets/sameba.webp','/assets/kaxeti.jpg'], 120, '—', 'Single day', 'Easy', '—', 'Day trip', 'EN · GE · RU', 24, 17, null, 'All year', '01-01', '12-31', 'Tbilisi, Liberty Square', '10:00', 'Same day, ~17:00 Tbilisi', 'Minibus', '6 – 24 people', '2 – 3 hours, easy', 'Half an hour from Tbilisi sits the old capital of the Georgian kingdom, where the country adopted Christianity in the 4th century. Jvari monastery on its hill, Svetitskhoveli cathedral below, and the confluence of the Mtkvari and Aragvi between them.', 41.8458, 44.7208, '[["Jvari → Svetitskhoveli → Tbilisi","Start at Jvari monastery for the view over the two rivers meeting, drive down into Mtskheta for Svetitskhoveli cathedral and the old town, with time for lunch before heading back."]]'::jsonb, '[]'::jsonb, '[]'::jsonb, true),
  ('kakheti-wine', 'Kakheti Wine Route', 'Wine route & qvevri cellars', 'culture', null, 'Kakheti', '/assets/kaxeti.jpg', array['/assets/kaxeti.jpg','/assets/kaxeti.jpe','/assets/kaxeti.jpeg','/assets/wine.svg'], 380, '—', '2 days / 1 night', 'Easy', '—', 'Guesthouse', 'EN · GE · RU', 20, 6, 'top', 'All year', '01-01', '12-31', 'Tbilisi, Liberty Square', '09:30', 'Day 2, ~19:00 Tbilisi', 'Minibus', '6 – 20 people', '2 – 3 hours, easy', 'Two days in the valley where wine has been made continuously for eight thousand years. Family marani cellars with clay qvevri buried to the neck, the hill town of Sighnaghi above the Alazani plain, and more amber wine than is strictly sensible.', 41.9192, 45.4731, '[["Tbilisi → Sighnaghi → Bodbe","Drive east to the walled town of Sighnaghi, walk the ramparts over the Alazani valley, visit Bodbe monastery, then a first family cellar and dinner with the hosts."],["Qvevri cellars → Tbilisi","Two more marani visits — one traditional qvevri maker, one modern estate — with a long supra lunch before the drive back."]]'::jsonb, '[]'::jsonb, '[]'::jsonb, true)
